non_null.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/microsoft/TypeScript/tsc/shim/scanner"
	"github.com/system-inc/adamic/internal/ir"
	"strings"
)

// nonNull uses the same nullish test and terminal panic as ?? panic(...).
// Recover presence checks from nullable loads, but keep a checked union narrowing
// in its result representation. Calls may invalidate the original narrowing.
func (l *lowering) nonNull(node *ast.Node) (ir.Expression, error) {
	operand := node.AsNonNullExpression().Expression
	value, err := l.expression(operand)
	if err != nil {
		return nil, err
	}
	return l.nonNullValue(node, value)
}

// nonNullValue also checks an already-held assignment target read.
func (l *lowering) nonNullValue(node *ast.Node, value ir.Expression) (ir.Expression, error) {
	operand := node.AsNonNullExpression().Expression
	var err error
	for {
		switch narrowed := value.(type) {
		case ir.Unwrap:
			value = narrowed.Value
		case ir.Defined:
			value = narrowed.Value
		default:
			// Narrow and narrowing calls retain their representation and checks.
			goto stored
		}
	}
stored:
	weakOperand := false
	if target, ok := value.(ir.WeakTarget); ok {
		// A narrowed Weak may have cleared since the narrowing. This assertion owns
		// the terminal check and its diagnostic, rather than the generic Weak load.
		target.Present = false
		value, weakOperand = target, true
	}
	if property, ok := value.(ir.Property); ok && ast.SkipParentheses(operand).Kind == ast.KindPropertyAccessExpression {
		if symbol := l.checker.GetSymbolAtLocation(ast.SkipParentheses(operand).Name()); symbol != nil {
			if declared, known := l.representation(l.checker.GetTypeOfSymbol(symbol)); known {
				property.Of = declared
				value = property
			}
		}
	}
	of, err := l.typeOf(node)
	flags := l.checker.GetTypeAtLocation(operand).Flags()
	if err != nil && (flags == checker.TypeFlagsUndefined || flags == checker.TypeFlagsNull) {
		of = ir.Object
		if contextual := l.checker.GetContextualType(node, checker.ContextFlagsNone); contextual != nil {
			if representation, known := l.representation(contextual); known {
				of = representation
			}
		}
		if of.IsMaybe() {
			of = of.Present()
		}
		if of == ir.Weak {
			of = ir.Object
		}
		if of == ir.Number || of == ir.Boolean {
			value = ir.MaybeOf{Of: ir.Maybe(of)}
		} else {
			value = ir.Undefined{Of: of}
		}
		err = nil
	}
	if err != nil {
		return nil, err
	}
	// A checked narrowing helper can already return a plain scalar. Its result
	// has no nullish representation and must never receive a pointer test.
	if value.Type() == ir.Number || value.Type() == ir.Boolean {
		l.recordNonNullCheck(node, true)
		return value, nil
	}
	proven := l.checker.GetTypeAtLocation(operand)
	if !weakOperand && !l.includesUndefined(proven) && !l.includesNull(proven) && !l.narrowedAway(ast.SkipParentheses(operand)) && !value.Type().IsMaybe() {
		if value.Type() == ir.Union && of != ir.Union {
			l.recordNonNullCheck(node, true)
			return ir.Narrow{Value: value, To: of}, nil
		}
		l.recordNonNullCheck(node, true)
		return value, nil
	}
	file := ast.GetSourceFileOfNode(node)
	text := file.Text()[scanner.GetTokenPosOfNode(node, file, false):node.End()]
	message := ir.StringConstant{Index: l.constant("non-null assertion failed at " + l.program.Where(node) + ": " + text + " is null or undefined")}
	result := ir.Expression(ir.Coalesce{Value: value, Panic: message, Of: value.Type().Present()})
	if result.Type() == ir.Union && of != ir.Union {
		result = ir.Narrow{Value: result, To: of}
	}
	l.recordNonNullCheck(node, false)
	return result, nil
}

func (l *lowering) checkedAssertionSource(node *ast.Node) bool {
	return strings.HasSuffix(l.program.FileName(ast.GetSourceFileOfNode(node)), ".ts")
}

func (l *lowering) recordNonNullCheck(node *ast.Node, proven bool) {
	counts := &l.result.NonNullChecks
	if proven {
		counts.Proven++
	} else {
		counts.Checked++
	}
	counts.Sites = append(counts.Sites, ir.NonNullCheck{Where: l.program.Where(node), Expression: sourceExpression(node), Proven: proven})
}

refusals.go:
package lower

import (
	"fmt"
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/microsoft/TypeScript/tsc/shim/scanner"
)

// refusal is one construct Adamic 0.1 doesn't allow (docs/0.1.md, "What's refused in 0.1"), and the
// fix to offer for it.
type refusal struct {
	what string
	fix  string
}

// refusals by syntax kind. Each is checked before lowering, so a program learns it has written
// something 0.1 refuses for good, never that stage 0 hasn't got to it yet.
var refusals = map[ast.Kind]refusal{
	ast.KindNonNullExpression: {"the non-null assertion !", "write ?? panic('why it can't be missing'), or narrow and handle the missing case"},
	ast.KindAwaitExpression:   {"await", "0.1 has no async; it arrives with the concurrency model"},
	ast.KindYieldExpression:   {"yield (generators)", "build an array, or call a function per item"},
	ast.KindDecorator:         {"a decorator", "write the behavior where it applies; 0.1 doesn't rewrite classes at runtime"},
	ast.KindWithStatement:     {"with", "name the object you mean"},
	ast.KindDeleteExpression:  {"delete", "an object's shape is fixed; use a Map for keys that come and go"},
	ast.KindIndexSignature:    {"an index signature", "use a Map, which keeps keys in the order they were added"},
	ast.KindExportAssignment:  {"export default", "export by name: one name for one thing"},
}

// refusedOperators are binary operators 0.1 refuses.
var refusedOperators = map[ast.Kind]refusal{
	ast.KindEqualsEqualsToken:      {"==", "use ===, which doesn't coerce"},
	ast.KindExclamationEqualsToken: {"!=", "use !==, which doesn't coerce"},
}

// refuse walks a module for what 0.1 refuses and returns the first, with where it is and the fix.
func (l *lowering) refuse(module *ast.SourceFile) error {
	// Use the parser's directives, which also recognize the block forms honored by the checker.
	// Text in a string or a prose comment never enters this list.
	if len(module.CommentDirectives) > 0 {
		directive := module.CommentDirectives[0]
		name := "@ts-ignore"
		if directive.Kind == ast.CommentDirectiveKindExpectError {
			name = "@ts-expect-error"
		}
		line, column := scanner.GetLineAndCharacterOfPosition(module, directive.Loc.Pos())
		return &Refused{Where: fmt.Sprintf("%s:%d:%d", l.program.FileName(module), line+1, column+1), What: name + " suppression directive", Fix: "remove it and fix the type error"}
	}
	// File-level checking pragmas are separate from line-suppression directives. Use every
	// parsed pragma, including one overridden by a later pragma, rather than just CheckJsDirective.
	for _, pragma := range module.Pragmas {
		if pragma.Name == "ts-nocheck" || pragma.Name == "ts-check" {
			line, column := scanner.GetLineAndCharacterOfPosition(module, pragma.Pos())
			return &Refused{Where: fmt.Sprintf("%s:%d:%d", l.program.FileName(module), line+1, column+1), What: "@" + pragma.Name + " checking pragma", Fix: "remove it and fix any type errors"}
		}
	}
	// Validate arguments before visiting their annotations, so a failed contract
	// names the actual argument and parameter even for an inline arrow.
	var contractError error
	var contracts ast.Visitor
	contracts = func(node *ast.Node) bool {
		if contractError != nil {
			return true
		}
		if node.Kind == ast.KindCallExpression {
			contractError = l.predicateArguments(node)
		}
		if contractError == nil {
			node.ForEachChild(contracts)
		}
		return contractError != nil
	}
	module.AsNode().ForEachChild(contracts)
	if contractError != nil {
		return contractError
	}
	var found error
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if found != nil {
			return true
		}
		if branch := l.literalCallableBranch(node); branch != nil {
			return visit(branch)
		}
		if node.Kind == ast.KindTypePredicate {
			found = l.predicateRefusal(node)
			return found != nil
		}
		if err := l.enumerationIndexedWriteRefusal(node); err != nil {
			found = err
			return true
		}
		if err := l.enumerationDescriptorRefusal(node); err != nil {
			found = err
			return true
		}
		if err := l.nodeLibraryRefusal(node); err != nil {
			found = err
			return true
		}
		if refused, isRefused := refusals[node.Kind]; isRefused && !(node.Kind == ast.KindIndexSignature && l.enumerationIndexSignature(node)) && (node.Kind != ast.KindNonNullExpression || !l.checkedAssertionSource(node)) {
			found = &Refused{Where: l.program.Where(node), What: refused.what, Fix: refused.fix}
			return true
		}
		if err := l.typedArrayUnsupported(node); err != nil {
			found = err
			return true
		}
		if node.Kind == ast.KindCallExpression {
			if err := l.predicateArguments(node); err != nil {
				found = err
				return true
			}
		}
		if err := l.enumRefusal(node); err != nil {
			found = err
			return true
		}
		checkedCast := false
		if node.Kind == ast.KindAsExpression {
			proof, err := l.castProof(node)
			if err != nil {
				found = err
				return true
			}
			checkedCast = proof.interfaceView || len(proof.allowed) > 0 || len(proof.classes) > 0
		}
		if err := l.namespaceRefusal(node); err != nil {
			found = err
			return true
		}
		if node.Kind == ast.KindBinaryExpression {
			if refused, isRefused := refusedOperators[node.AsBinaryExpression().OperatorToken.Kind]; isRefused {
				found = &Refused{Where: l.program.Where(node.AsBinaryExpression().OperatorToken), What: refused.what, Fix: refused.fix}
				return true
			}
		}
		generator := false
		switch node.Kind {
		case ast.KindFunctionDeclaration:
			generator = node.AsFunctionDeclaration().AsteriskToken != nil
		case ast.KindFunctionExpression:
			generator = node.AsFunctionExpression().AsteriskToken != nil
		case ast.KindMethodDeclaration:
			generator = node.AsMethodDeclaration().AsteriskToken != nil
		}
		if generator {
			found = &Refused{Where: l.program.Where(node), What: "a generator function", Fix: "use an explicit iterator object; suspended frames need ownership and cancellation rules before generators can be compiled without a collector (docs/user-iterators.md)"}
			return true
		}
		if ast.IsFunctionLike(node) && ast.HasSyntacticModifier(node, ast.ModifierFlagsAsync) {
			found = &Refused{Where: l.program.Where(node), What: "an async function", Fix: "0.1 has no async; it arrives with the concurrency model"}
			return true
		}
		if node.Kind == ast.KindIdentifier && node.Text() == "arguments" {
			// JavaScript's arguments object, not a variable the program named arguments.
			if symbol := l.checker.GetSymbolAtLocation(node); symbol != nil && len(symbol.Declarations) == 0 {
				if err := l.argumentsRefusal(node); err != nil {
					found = err
					return true
				}
			}
		}
		if (node.Kind == ast.KindPropertyAccessExpression || node.Kind == ast.KindElementAccessExpression) && !called(node) {
			if err := l.nodeBufferUnsupportedUse(node); err != nil {
				found = err
				return true
			}
		}
		if node.Kind == ast.KindShorthandPropertyAssignment {
			if symbol := l.checker.GetShorthandAssignmentValueSymbol(node); symbol != nil && len(symbol.Declarations) == 1 && symbol.Declarations[0].Kind == ast.KindVariableDeclaration {
				if initializer := symbol.Declarations[0].AsVariableDeclaration().Initializer; initializer != nil {
					if _, known := l.libraryMethod(initializer, map[*ast.Symbol]bool{}); known {
						found = l.notYet(node, "a library method value outside a const alias (an object field erases its receiver and callable ABI); use an arrow")
						return true
					}
				}
			}
		}
		if node.Kind == ast.KindPropertyAccessExpression && !called(node) && !l.libraryNumberBoundMethod(node) && !l.stringMethodObservation(node) && !l.libraryArrayObservedMethod(node) && !l.libraryMethodReadAllowed(node) {
			// A method read as a value loses its object: this is undefined when it's called.
			access := node.AsPropertyAccessExpression()
			if access.Name().Text() == "isPrototypeOf" && l.libraryMember(node) {
				found = l.prototypeRead(node, "isPrototypeOf")
				return true
			}
			// Math.random has its own refusal, called or not.
			isRandom := l.isLibraryGlobal(access.Expression, "Math") && access.Name().Text() == "random"
			if symbol := l.checker.GetSymbolAtLocation(node); symbol != nil && symbol.Flags&ast.SymbolFlagsMethod != 0 && !isRandom {
				object := "its object"
				if ast.IsIdentifier(access.Expression) || access.Expression.Kind == ast.KindThisKeyword {
					object = scannedText(access.Expression)
				}
				parameters := "value"
				if signatures := l.checker.GetSignaturesOfType(l.checker.GetTypeOfSymbol(symbol), checker.SignatureKindCall); len(signatures) > 0 {
					names := []string{}
					for _, parameter := range signatures[0].Parameters() {
						names = append(names, parameter.Name)
					}
					parameters = strings.Join(names, ", ")
				}
				found = &Refused{Where: l.program.Where(node), What: "a method read as a value (" + symbol.Name + " would lose its object, and this with it)", Fix: "call it in an arrow that keeps the object: (" + parameters + ") => " + object + "." + symbol.Name + "(" + parameters + ") (unbound-method)"}
				return true
			}
		}
		if node.Kind == ast.KindClassDeclaration {
			if err := l.checkOverrides(node, l.checker.GetTypeAtLocation(node.Name())); err != nil {
				found = err
				return true
			}
		}
		// Prefer the writable-slot explanation when both a mutable view and nominal ancestry fail.
		// A checked cast relates only members selected by its tag, not excluded source members.
		if !checkedCast {
			if err := l.refuseStringWidening(node); err != nil {
				found = err
				return true
			}
		}
		if err := l.refuseOptionalWidening(node); err != nil {
			found = err
			return true
		}
		if err := l.classViewRefusal(node); err != nil {
			found = err
			return true
		}
		node.ForEachChild(visit)
		return false
	}
	module.AsNode().ForEachChild(visit)
	return found
}

// called reports whether a property access is what a call calls, through any parentheses around it:
// a method called on its object, which keeps it.
func called(node *ast.Node) bool {
	for node.Parent != nil && node.Parent.Kind == ast.KindParenthesizedExpression {
		node = node.Parent
	}
	return node.Parent != nil && node.Parent.Kind == ast.KindCallExpression && node.Parent.AsCallExpression().Expression == node
}

// scannedText is an identifier's name, or this.
func scannedText(node *ast.Node) string {
	if node.Kind == ast.KindThisKeyword {
		return "this"
	}
	return node.Text()
}

optional_indexing_map.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

// A Map lookup guards the receiver, not the library method. The key is
// evaluated only after that guard and the ordinary lookup keeps undefined.
func (l *lowering) optionalMapGet(node *ast.Node) (ir.Expression, bool, error) {
	call := node.AsCallExpression()
	callee := ast.SkipParentheses(call.Expression)
	if call.QuestionDotToken != nil || callee.Kind != ast.KindPropertyAccessExpression {
		return nil, false, nil
	}
	access := callee.AsPropertyAccessExpression()
	if access.QuestionDotToken == nil || access.Name().Text() != "get" || !l.libraryMember(callee) {
		return nil, false, nil
	}
	proven := l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(access.Expression))
	if !l.isLibraryType(proven, "Map", "ReadonlyMap") {
		return nil, false, nil
	}
	if len(call.Arguments.Nodes) != 1 || hasSpread(node) {
		return nil, true, l.notYet(node, "an optional Map get with other than one key")
	}
	if l.optionalMapStructuralReceiver(access.Expression) {
		return nil, true, l.notYet(node, "an optional Map get through a structural receiver")
	}

	types := l.typeArguments(proven)
	if len(types) != 2 {
		return nil, true, l.notYet(node, "an optional Map get without key and value types")
	}
	keyType, keyKnown := l.representation(types[0])
	valueType, valueKnown := l.kept(types[1])
	if !keyKnown || !keyable(keyType) || !valueKnown || (slotless(valueType) && !(valueType == ir.Union && l.writable(types[1]))) {
		return nil, true, l.notYet(node, "an optional Map get with unsupported key or value storage")
	}
	base, err := l.expression(access.Expression)
	if err != nil {
		return nil, true, err
	}
	key, err := l.expression(call.Arguments.Nodes[0])
	if err != nil {
		return nil, true, err
	}
	key = fit(key, keyType)
	if base.Type() != ir.Map || key.Type() != keyType {
		return nil, true, l.notYet(node, "an optional Map get with incompatible receiver or key storage")
	}
	function := -1
	if l.function != nil {
		function = l.functionIndex
	}
	local := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "optional_map_base", Type: ir.Map, Function: function, ExpressionAssigned: true})
	read := ir.Read{Local: local, Of: ir.Map}
	value := ir.MapGet{Map: read, Key: key, KeyType: keyType, ValueType: valueType}
	of := value.Type()
	return ir.Effects{Body: []ir.Statement{ir.Declare{Local: local, Value: base}}, Result: ir.Conditional{
		Condition: ir.Unary{Operator: ir.Not, Operand: ir.Binary{Operator: ir.Or, Left: ir.IsUndefined{Value: read}, Right: ir.IsNull{Value: read}}},
		WhenTrue:  value, WhenNot: fit(ir.Undefined{}, of), Of: of,
	}}, true, nil
}

// A library interface alone does not prove the receiver uses native Map storage.
// Keep compatible object literals and constructed custom receivers out of the
// intrinsic path, including ones hidden behind a ReadonlyMap annotation.
func (l *lowering) optionalMapStructuralReceiver(receiver *ast.Node) bool {
	view := l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(receiver))
	modules, err := l.moduleOrder(l.program.Files()[0])
	if err != nil {
		return true
	}
	hazard := false
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if hazard {
			return true
		}
		if node.Kind == ast.KindObjectLiteralExpression || node.Kind == ast.KindNewExpression {
			shape := l.checker.GetTypeAtLocation(node)
			if l.checker.IsTypeAssignableTo(shape, view) {
				representation, known := l.representation(shape)
				member := l.checker.GetPropertyOfType(shape, "get")
				if !known || representation != ir.Map || member == nil || !l.librarySymbol(member) {
					hazard = true
					return true
				}
			}
		}
		node.ForEachChild(visit)
		return false
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
	}
	return hazard
}

optional_indexing.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

// Save the base before the guard. The index belongs only to the present arm,
// and the ordinary lookup retains its missing-element representation.
func (l *lowering) optionalIndex(node *ast.Node, base ir.Expression) (ir.Expression, error) {
	function := -1
	if l.function != nil {
		function = l.functionIndex
	}
	local := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "optional_index_base", Type: base.Type(), Function: function, ExpressionAssigned: true})
	read := ir.Read{Local: local, Of: base.Type()}
	value, err := l.optionalIndexValue(node, read)
	if err != nil {
		return nil, err
	}
	of := value.Type()
	return ir.Effects{Body: []ir.Statement{ir.Declare{Local: local, Value: base}}, Result: ir.Conditional{
		Condition: ir.Unary{Operator: ir.Not, Operand: ir.Binary{Operator: ir.Or, Left: ir.IsUndefined{Value: read}, Right: ir.IsNull{Value: read}}},
		WhenTrue:  value, WhenNot: fit(ir.Undefined{}, of), Of: of,
	}}, nil
}

func (l *lowering) optionalIndexValue(node *ast.Node, base ir.Expression) (ir.Expression, error) {
	access := node.AsElementAccessExpression()
	index, err := l.expression(access.ArgumentExpression)
	if err != nil {
		return nil, err
	}
	if index.Type() != ir.Number {
		return nil, l.notYet(node, "an optional index that isn't a number")
	}
	var value ir.Expression
	if base.Type() == ir.String {
		value = ir.StringIndex{Value: base, Index: index}
	} else {
		element := ir.Number
		if !base.Type().IsTypedArray() {
			element, err = l.elementType(access.Expression)
			if err != nil {
				return nil, err
			}
		}
		value = ir.ArrayIndex{Array: base, Index: index, Element: element}
	}
	return value, nil
}

optional_widening.go:
package lower

import (
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
)

// optionalWidening names the relation whose optional field could be hidden by a structural view.
// This is independent of mutable invariance: even a readonly optional field can lie on a read.
type optionalWidening struct {
	property       string
	source, target *checker.Type
}

func (l *lowering) optionalWidened(source, target *checker.Type, skip map[string]bool, visited map[[2]*checker.Type]bool) *optionalWidening {
	if source == nil || target == nil {
		return nil
	}
	if weak := l.weakTarget(source); weak != nil {
		source = weak
	}
	if weak := l.weakTarget(target); weak != nil {
		target = weak
	}
	// Only an accepted assignment is a widening. Function rest parameters and checked
	// downcasts can pair unrelated types; those belong to their own relation rules.
	if skip == nil && !l.checker.IsTypeAssignableTo(source, target) {
		return nil
	}
	if source == target || visited[[2]*checker.Type{source, target}] {
		return nil
	}
	visited[[2]*checker.Type{source, target}] = true
	if source.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range source.Types() {
			if found := l.optionalWidened(member, target, skip, visited); found != nil {
				return found
			}
		}
		return nil
	}
	if target.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range target.Types() {
			if l.checker.IsTypeAssignableTo(source, member) {
				if found := l.optionalWidened(source, member, skip, visited); found != nil {
					return found
				}
			}
		}
		return nil
	}
	if source.Flags()&checker.TypeFlagsTypeParameter != 0 {
		return l.optionalWidened(l.checker.GetBaseConstraintOfType(source), target, skip, visited)
	}
	if target.Flags()&checker.TypeFlagsTypeParameter != 0 {
		return l.optionalWidened(source, l.checker.GetBaseConstraintOfType(target), skip, visited)
	}
	if source.Flags()&(checker.TypeFlagsObject|checker.TypeFlagsIntersection) == 0 || target.Flags()&(checker.TypeFlagsObject|checker.TypeFlagsIntersection) == 0 {
		return nil
	}
	// Container elements are views too. Avoid walking library methods, whose generic signatures
	// describe operations rather than value fields.
	if (l.checker.IsArrayType(source) || checker.IsTupleType(source)) && (l.checker.IsArrayType(target) || checker.IsTupleType(target)) {
		sources, targets := l.checker.GetTypeArguments(source), l.checker.GetTypeArguments(target)
		for index, inside := range sources {
			at := index
			if !checker.IsTupleType(target) {
				at = 0
			}
			if at < len(targets) {
				if found := l.optionalWidened(inside, targets[at], nil, visited); found != nil {
					return found
				}
			}
		}
		return nil
	}
	for _, property := range l.checker.GetPropertiesOfType(target) {
		if skip[property.Name] {
			continue
		}
		declared := l.checker.GetPropertyOfType(source, property.Name)
		if declared == nil {
			if property.Flags&ast.SymbolFlagsOptional != 0 && !isClassInstance(source) {
				return &optionalWidening{property: property.Name, source: source, target: target}
			}
			continue
		}
		if found := l.optionalWidened(l.checker.GetTypeOfSymbol(declared), l.checker.GetTypeOfSymbol(property), nil, visited); found != nil {
			return found
		}
	}
	sources := l.checker.GetSignaturesOfType(source, checker.SignatureKindCall)
	targets := l.checker.GetSignaturesOfType(target, checker.SignatureKindCall)
	if len(sources) == 1 && len(targets) == 1 && len(sources[0].TypeParameters()) == 0 && len(targets[0].TypeParameters()) == 0 {
		if found := l.optionalWidened(l.checker.GetReturnTypeOfSignature(sources[0]), l.checker.GetReturnTypeOfSignature(targets[0]), nil, visited); found != nil {
			return found
		}
		takes, gives := sources[0].Parameters(), targets[0].Parameters()
		for index := 0; index < len(takes) && index < len(gives); index++ {
			if found := l.optionalWidened(l.checker.GetTypeOfSymbol(gives[index]), l.checker.GetTypeOfSymbol(takes[index]), nil, visited); found != nil {
				return found
			}
		}
	}
	return nil
}

func (l *lowering) optionalValue(node *ast.Node, target *checker.Type) *optionalWidening {
	node = ast.SkipParentheses(node)
	switch node.Kind {
	case ast.KindObjectLiteralExpression, ast.KindArrayLiteralExpression:
		// The literal's fields, spreads and elements are checked separately at their own sites.
		return nil
	case ast.KindConditionalExpression:
		conditional := node.AsConditionalExpression()
		for _, branch := range []*ast.Node{conditional.WhenTrue, conditional.WhenFalse} {
			if found := l.optionalValue(branch, target); found != nil {
				return found
			}
		}
		return nil
	}
	return l.optionalWidened(l.checker.GetTypeAtLocation(node), target, nil, map[[2]*checker.Type]bool{})
}

// optionalAtSite uses the same relation sites as the other view rules, before lowering.
// A leading spread is not proof of absence: it copies fields hidden by the source's type too.
func (l *lowering) optionalAtSite(node *ast.Node) *optionalWidening {
	if l.nodeFSFileReadOnlyArgument(node) {
		return nil
	}
	// Only argument positions of a directly imported node:* call can use the host exemption.
	if parent := node.Parent; parent != nil && parent.Kind == ast.KindCallExpression && l.optionalNodeHostCall(parent) {
		for index, argument := range parent.AsCallExpression().Arguments.Nodes {
			if argument == node && l.nodeHostConsumesArgument(parent, index) {
				return nil
			}
		}
	}
	var found *optionalWidening
	switch node.Kind {
	case ast.KindAsExpression:
		found = l.optionalValue(node.AsAsExpression().Expression, l.checker.GetTypeAtLocation(node))
	case ast.KindShorthandPropertyAssignment:
		target := l.checker.GetContextualType(node.Parent, checker.ContextFlagsNone)
		if target != nil {
			found = l.optionalValue(node.Name(), l.checker.GetTypeOfPropertyOfType(target, node.Name().Text()))
		}
	case ast.KindSpreadAssignment:
		target := l.checker.GetContextualType(node.Parent, checker.ContextFlagsNone)
		if target == nil {
			return nil
		}
		skip := map[string]bool{}
		after := false
		for _, property := range node.Parent.AsObjectLiteralExpression().Properties.Nodes {
			if property == node {
				after = true
			} else if after && property.Name() != nil {
				skip[property.Name().Text()] = true
			}
		}
		expression := ast.SkipParentheses(node.AsSpreadAssignment().Expression)
		if expression.Kind != ast.KindObjectLiteralExpression {
			found = l.optionalWidened(l.checker.GetTypeAtLocation(expression), target, skip, map[[2]*checker.Type]bool{})
		}
	default:
		if node.Kind == ast.KindParenthesizedExpression || !l.isExpression(node) || l.genericFunction(node) {
			return nil
		}
		var target *checker.Type
		if viewSite(node) {
			target = l.checker.GetContextualType(node, checker.ContextFlagsNone)
		}
		if target == nil {
			target = l.impliedTarget(node)
		}
		if target == nil {
			return nil
		}
		found = l.optionalValue(node, target)
	}
	return found
}

func (l *lowering) refuseOptionalWidening(node *ast.Node) error {
	found := l.optionalAtSite(node)
	if found == nil {
		return nil
	}
	return &Refused{Where: l.program.Where(node),
		What: "optional property " + found.property + " in " + l.checker.TypeToString(found.target) + " absent from structural source " + l.checker.TypeToString(found.source) + ", which can hide fields",
		Fix:  "declare " + found.property + " on the source type, or build a fresh object with known fields (adamic/no-optional-widening)"}
}

// Resolve the import binding rather than trusting the callee's spelling.
func (l *lowering) optionalNodeHostCall(call *ast.Node) bool {
	callee := ast.SkipParentheses(call.AsCallExpression().Expression)
	if callee.Kind == ast.KindPropertyAccessExpression {
		callee = ast.SkipParentheses(callee.AsPropertyAccessExpression().Expression)
	}
	symbol := l.checker.GetSymbolAtLocation(callee)
	if symbol == nil {
		return false
	}
	for _, declaration := range symbol.Declarations {
		for ancestor := declaration; ancestor != nil; ancestor = ancestor.Parent {
			if ancestor.Kind == ast.KindImportDeclaration {
				specifier := ancestor.ModuleSpecifier()
				return specifier != nil && strings.HasPrefix(specifier.Text(), "node:")
			}
		}
	}
	return false
}

generic.go:
package lower

import (
	"strconv"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// maximumGenericDepth is how many instantiations of generic functions may be lowered inside one
// another. Ordinary programs nest a few; a function that calls itself with an ever larger type
// (polymorphic recursion) would instantiate without end, and 0.1 refuses it (docs/0.1.md).
const maximumGenericDepth = 32

// instantiateFunction lowers a generic module function for the type arguments of one call, once per
// distinct set of checker type identities, as a generic class is (instantiate). Within it,
// each type parameter is what this call made it.
//
// The checker resolves the call's signature with its type arguments substituted, but doesn't export
// the mapping itself, so it's read back the way it was made: each declared parameter's type, and the
// result's, against the resolved signature's, through arrays and tuples. A type parameter that can't
// be read back that way is left unmapped, and the body says not yet wherever it needs to know it.
func (l *lowering) instantiateFunction(call *ast.Node, declaration *ast.Node) (int, error) {
	resolved := l.checker.GetResolvedSignature(call)
	target := l.checker.GetSignatureFromDeclaration(declaration)
	if resolved == nil || target == nil {
		return 0, l.notYet(call, "a call to a generic function whose signature the checker didn't resolve")
	}
	concreteTypes := map[*checker.Type]*checker.Type{}
	// Class-generic calls supply this callee's resolved mapper. Ordinary recursive
	// calls must infer their own arguments: the outer mapper can still describe the
	// same declaration's previous instantiation, as nest<T>([item], depth - 1) does.
	if l.genericUsesClasses(declaration, map[*ast.Node]bool{}) {
		for _, parameter := range declaration.TypeParameters() {
			declaredType := l.checker.GetTypeAtLocation(parameter.Name())
			concrete := l.concrete(declaredType)
			if concrete != declaredType && concrete.Flags()&checker.TypeFlagsTypeParameter == 0 {
				concreteTypes[declaredType] = concrete
			}
		}
	}
	declared, given := target.Parameters(), resolved.Parameters()
	for index := range declared {
		if index < len(given) {
			l.inferTypes(l.checker.GetTypeOfSymbol(declared[index]), l.checker.GetTypeOfSymbol(given[index]), concreteTypes)
		}
	}
	l.inferTypes(l.checker.GetReturnTypeOfSignature(target), l.checker.GetReturnTypeOfSignature(resolved), concreteTypes)

	// An explicit type argument can make tsc view a mutable argument through a wider type without
	// giving the argument that contextual type. Judge the instantiated parameter directly: the
	// ordinary refusal walk cannot see this view at the argument node.
	if call.AsCallExpression().TypeArguments != nil && len(call.AsCallExpression().TypeArguments.Nodes) > 0 {
		for index, argument := range call.AsCallExpression().Arguments.Nodes {
			if index >= len(given) || argument.Kind == ast.KindObjectLiteralExpression || argument.Kind == ast.KindArrayLiteralExpression {
				continue
			}
			from, to := l.checker.GetTypeAtLocation(argument), l.checker.GetTypeOfSymbol(given[index])
			if found := l.widened(from, to, map[[2]*checker.Type]bool{}); found != nil {
				return 0, &Refused{Where: l.program.Where(argument), What: "a type argument makes a value of type " + l.checker.TypeToString(from) + " seen as " + l.checker.TypeToString(to) + ", which can write " + l.checker.TypeToString(found.target) + " where " + l.checker.TypeToString(found.source) + " is read", Fix: "use the value's invariant type argument, or make the parameter readonly (adamic/invariant-mutable)"}
			}
		}
	}

	substitution := map[*checker.Type]ir.Type{}

	owner := -1
	if local, ok := l.locals[l.symbol(declaration.Name())]; ok && l.result.Locals[local].NestedFunction < 0 {
		owner = l.result.Locals[local].Function
	}
	key := l.program.Where(declaration)
	name := declaration.Name().Text()
	if owner >= 0 {
		key += ",frame:" + strconv.Itoa(owner)
	}
	for _, parameter := range declaration.TypeParameters() {
		parameterType := l.checker.GetTypeAtLocation(parameter.Name())
		concrete, isKnown := concreteTypes[parameterType]
		if !isKnown {
			// Not read back (it stands only inside a union or an object, Result<Value>): left
			// unmapped, so whatever in the body needs to know how it's held says not yet, there.
			key += ",unread"
			name += "_unread"
			continue
		}
		held, hasRepresentation := l.representation(concrete)
		if !hasRepresentation {
			key += ",unread"
			name += "_unread"
			continue
		}
		substitution[parameterType] = held
		key += "," + l.genericTypeKey(concrete)
	}
	if existing, isLowered := l.genericInstances[key]; isLowered {
		return existing, nil
	}
	if l.genericDepth >= maximumGenericDepth {
		return 0, &Refused{Where: l.program.Where(call), What: "a generic function instantiated without end (polymorphic recursion)", Fix: "call it with the same type arguments it was called with, or write a function per type"}
	}

	index := len(l.result.Functions)
	name += "_" + strconv.Itoa(index)
	l.result.Functions = append(l.result.Functions, ir.Function{Name: name, Closure: owner >= 0, NestedParent: owner + 1})
	if l.genericInstances == nil {
		l.genericInstances = map[string]int{}
	}
	l.genericInstances[key] = index

	// Lower with this instantiation's meaning of each type parameter, and locals of its own, outside
	// whatever function or closure called it.
	outerSubstitution, outerLocals, outerClosures, outerTypeMapper := l.substitution, l.locals, l.closures, l.typeMapper
	l.substitution, l.closures = substitution, nil
	if owner >= 0 {
		for proven, held := range outerSubstitution {
			if _, ok := substitution[proven]; !ok {
				substitution[proven] = held
			}
		}
		l.closures = append(append([]int{}, outerClosures...), index)
	}
	sources, targets := []*checker.Type{}, []*checker.Type{}
	for _, parameter := range declaration.TypeParameters() {
		parameterType := l.checker.GetTypeAtLocation(parameter.Name())
		if concrete, ok := concreteTypes[parameterType]; ok {
			sources, targets = append(sources, parameterType), append(targets, concrete)
		}
	}
	if len(sources) > 0 {
		l.typeMapper = newTypeMapper(sources, targets)
	}
	if err := l.refuseInstantiatedMutation(declaration); err != nil {
		return 0, err
	}
	l.locals = map[*ast.Symbol]int{}
	for symbol, local := range outerLocals {
		if l.result.Locals[local].Global || owner >= 0 {
			l.locals[symbol] = local
		}
	}
	l.genericDepth++
	defer func() {
		l.substitution, l.locals, l.closures, l.typeMapper = outerSubstitution, outerLocals, outerClosures, outerTypeMapper
		l.genericDepth--
	}()
	if owner >= 0 {
		l.closureRecords = append(l.closureRecords, closureRecord{proven: l.concrete(l.checker.GetTypeAtLocation(declaration.Name())), function: index, node: declaration})
	}
	if err := l.lowerFunction(index, declaration, -1); err != nil {
		return 0, err
	}
	return index, nil
}

// genericTypeKey is the shared identity key for class and function type arguments.
// Keep the concrete representatives in instantiated, the type universe the cycle
// finder already visits. Checker identity includes union members, nested containers,
// signatures and structural fields; a native representation alone loses those facts.
// This is also where nullable representations can extend the key.
func (l *lowering) genericTypeKey(proven *checker.Type) string {
	held, known := l.representation(proven)
	if !known {
		return "unread"
	}
	for index, representative := range l.instantiated {
		if identicalTypes(l.checker, proven, representative) {
			return typeName(held) + ":" + strconv.Itoa(index)
		}
	}
	index := len(l.instantiated)
	l.instantiated = append(l.instantiated, proven)
	return typeName(held) + ":" + strconv.Itoa(index)
}

// refuseInstantiatedMutation checks writes whose safety depends on a type parameter's constraint.
// TypeScript checks the generic body against the constraint, so Pack extends Animal[] permits a Cat
// to be pushed. An instantiation with Pack = Dog[] would then put that Cat in a Dog[]; monomorphizing
// the body must recheck that write against Dog rather than trusting the wider constraint.
// JSON inputs also need their concrete schemas checked before lowering can erase their types.
func (l *lowering) refuseInstantiatedMutation(declaration *ast.Node) error {
	var refused error
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if refused != nil {
			return true
		}
		if node.Kind == ast.KindCallExpression {
			call := node.AsCallExpression()
			callee := ast.SkipParentheses(call.Expression)
			if callee.Kind == ast.KindPropertyAccessExpression && callee.Name().Text() == "stringify" && l.isLibraryGlobal(callee.AsPropertyAccessExpression().Expression, "JSON") {
				for _, argument := range call.Arguments.Nodes {
					if err := l.checkInstantiatedJSONInput(argument); err != nil {
						refused = err
						return true
					}
				}
			}
			if callee.Kind == ast.KindPropertyAccessExpression {
				receiver := callee.AsPropertyAccessExpression().Expression
				argumentIndex, typeIndex := -1, -1
				switch callee.Name().Text() {
				case "push", "add":
					argumentIndex, typeIndex = 0, 0
				case "set":
					argumentIndex, typeIndex = 1, 1
				}
				concrete := l.concrete(l.checker.GetTypeAtLocation(receiver))
				if argumentIndex < 0 || concrete.Flags()&checker.TypeFlagsObject == 0 || concrete.ObjectFlags()&checker.ObjectFlagsReference == 0 {
					return node.ForEachChild(visit)
				}
				arguments := l.checker.GetTypeArguments(concrete)
				if argumentIndex >= 0 && argumentIndex < len(call.Arguments.Nodes) && typeIndex < len(arguments) {
					argument := call.Arguments.Nodes[argumentIndex]
					from, to := l.concrete(l.checker.GetTypeAtLocation(argument)), arguments[typeIndex]
					if !l.checker.IsTypeAssignableTo(from, to) {
						refused = &Refused{Where: l.program.Where(argument), What: "instantiating a generic function makes a value of type " + l.checker.TypeToString(from) + " written where " + l.checker.TypeToString(to) + " is read", Fix: "make the collection readonly, or use a type parameter for the value being written (adamic/invariant-mutable)"}
						return true
					}
				}
			}
		}
		return node.ForEachChild(visit)
	}
	declaration.ForEachChild(visit)
	return refused
}

// inferTypes records what each type parameter in declared stands for, by where it stands in
// instantiated: the type itself, a referenced type's arguments, or a function's parameters and
// result. The caller's type mapper makes an outer function's parameter concrete before it is saved,
// so a generic function calling another with its own type parameter passes the concrete type on.
func (l *lowering) inferTypes(declared *checker.Type, instantiated *checker.Type, into map[*checker.Type]*checker.Type) {
	if declared == nil || instantiated == nil {
		return
	}
	// Optional implementation parameters and results can wrap the same generic
	// binder that the resolved overload exposes directly. Infer from the present
	// member; an absent argument supplies no evidence about that binder.
	if declared.Flags()&checker.TypeFlagsUnion != 0 && l.censusHasUndefined(declared) {
		present := []*checker.Type{}
		for _, member := range declared.Types() {
			if member.Flags()&checker.TypeFlagsUndefined == 0 {
				present = append(present, member)
			}
		}
		given := instantiated
		if l.censusHasUndefined(given) && given.Flags()&checker.TypeFlagsUnion != 0 {
			members := []*checker.Type{}
			for _, member := range given.Types() {
				if member.Flags()&checker.TypeFlagsUndefined == 0 {
					members = append(members, member)
				}
			}
			given = l.checker.GetUnionType(members)
		}
		// GetNonNullableType also turns a rigid T into T & {}. Removing only
		// the optional member preserves the binder we are trying to infer.
		if len(present) == 1 && given.Flags()&checker.TypeFlagsUndefined == 0 {
			l.inferTypes(present[0], given, into)
		}
		return
	}
	if declared.Flags()&checker.TypeFlagsUnion != 0 {
		var missing *checker.Type
		for _, member := range declared.Types() {
			known, found := into[member]
			if !found && member.Flags()&checker.TypeFlagsTypeParameter != 0 {
				if missing != nil {
					return // More than one unknown binder has no unique witness.
				}
				missing = member
				continue
			}
			if !found {
				known = l.concrete(member)
			}
			if !l.checker.IsTypeAssignableTo(known, l.concrete(instantiated)) {
				return
			}
		}
		if missing != nil {
			into[missing] = l.concrete(instantiated)
		}
		return
	}
	if declared.Flags()&checker.TypeFlagsTypeParameter != 0 {
		if _, isSet := into[declared]; !isSet {
			into[declared] = l.concrete(instantiated)
		}
		return
	}
	if declared.Flags()&checker.TypeFlagsObject != 0 && instantiated.Flags()&checker.TypeFlagsObject != 0 {
		if declared.ObjectFlags()&checker.ObjectFlagsReference != 0 && instantiated.ObjectFlags()&checker.ObjectFlagsReference != 0 {
			declaredArguments, instantiatedArguments := l.checker.GetTypeArguments(declared), l.checker.GetTypeArguments(instantiated)
			for index := range declaredArguments {
				if index < len(instantiatedArguments) {
					l.inferTypes(declaredArguments[index], instantiatedArguments[index], into)
				}
			}
		}
		declaredSignatures, instantiatedSignatures := l.checker.GetSignaturesOfType(declared, checker.SignatureKindCall), l.checker.GetSignaturesOfType(instantiated, checker.SignatureKindCall)
		if len(declaredSignatures) > 0 && len(instantiatedSignatures) > 0 {
			declaredParameters, instantiatedParameters := declaredSignatures[0].Parameters(), instantiatedSignatures[0].Parameters()
			for index := range declaredParameters {
				if index < len(instantiatedParameters) {
					l.inferTypes(l.checker.GetTypeOfSymbol(declaredParameters[index]), l.checker.GetTypeOfSymbol(instantiatedParameters[index]), into)
				}
			}
			l.inferTypes(l.checker.GetReturnTypeOfSignature(declaredSignatures[0]), l.checker.GetReturnTypeOfSignature(instantiatedSignatures[0]), into)
		}
	}
}

// JSON descriptors must be checked against the actual type arguments too. Without
// this check a type parameter can hide a container inside the scalar union schema.
func (l *lowering) checkInstantiatedJSONInput(node *ast.Node) error {
	node = ast.SkipParentheses(node)
	if node.Kind == ast.KindNullKeyword {
		return nil
	}
	if node.Kind == ast.KindArrayLiteralExpression {
		for _, element := range node.AsArrayLiteralExpression().Elements.Nodes {
			if element.Kind == ast.KindSpreadElement || element.Kind == ast.KindOmittedExpression {
				continue
			}
			if err := l.checkInstantiatedJSONInput(element); err != nil {
				return err
			}
		}
		return nil
	}
	if node.Kind == ast.KindObjectLiteralExpression {
		for _, field := range node.AsObjectLiteralExpression().Properties.Nodes {
			if field.Kind == ast.KindPropertyAssignment {
				if err := l.checkInstantiatedJSONInput(field.AsPropertyAssignment().Initializer); err != nil {
					return err
				}
			}
		}
		return nil
	}
	concrete := l.concrete(l.checker.GetTypeAtLocation(node))
	if concrete.Flags()&checker.TypeFlagsUnion != 0 {
		held, known := l.representation(concrete)
		if known && held == ir.Union {
			for _, member := range concrete.Types() {
				if l.checker.IsArrayType(member) {
					return l.notYet(node, "JSON.stringify unions containing arrays (adamic/json-union-array)")
				}
			}
		}
	}
	_, err := l.jsonType(node, concrete, 0)
	return err
}

class_inheritance.go:
package lower

import (
	"slices"
	"strconv"
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
)

func (l *lowering) baseInstance(declaration *ast.Node, classType *checker.Type) (*instance, error) {
	for _, clause := range nodesOf(declaration.AsClassDeclaration().HeritageClauses) {
		if clause.AsHeritageClause().Token != ast.KindExtendsKeyword {
			continue
		}
		types := clause.AsHeritageClause().Types.Nodes
		if len(types) != 1 || !ast.IsIdentifier(ast.SkipParentheses(types[0].AsExpressionWithTypeArguments().Expression)) {
			return nil, l.notYet(clause, "a computed class base; name the base class directly")
		}
		bases := l.classBases(classType)
		if len(bases) != 1 {
			return nil, l.notYet(clause, "a class base whose type isn't known")
		}
		baseType := bases[0]
		symbol := baseType.Symbol()
		if symbol == nil || len(symbol.Declarations) != 1 || symbol.Declarations[0].Kind != ast.KindClassDeclaration {
			return nil, l.notYet(clause, "a base that isn't a declared class")
		}
		base := symbol.Declarations[0]
		return l.instantiate(base, baseType, clause)
	}
	return nil, nil
}

// TypeScript compares methods bivariantly and mutable properties covariantly. Neither is safe
// through a base reference: arguments flow into the override, and fields can be written through it.
func (l *lowering) checkOverrides(declaration *ast.Node, classType *checker.Type) error {
	bases := l.classBases(classType)
	if len(bases) == 0 {
		return nil
	}
	return l.checkMemberOverrides(declaration, classType, bases[0], false)
}

func (l *lowering) checkMemberOverrides(declaration *ast.Node, classType, base *checker.Type, static bool) error {
	checkABI := static || len(declaration.TypeParameters()) == 0 || classType != l.checker.GetTypeAtLocation(declaration.Name())
	for _, member := range classMembersWithParameters(declaration) {
		if member.Name() == nil || ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic) != static {
			continue
		}
		inherited := l.checker.GetPropertyOfType(base, member.Name().Text())
		if inherited == nil {
			continue
		}
		own := l.checker.GetTypeAtLocation(member.Name())
		if property := l.checker.GetPropertyOfType(classType, member.Name().Text()); property != nil {
			own = l.checker.GetTypeOfSymbol(property)
		}
		previous := l.checker.GetTypeOfSymbol(inherited)
		refuse := func(what, fix string) error { return &Refused{Where: l.program.Where(member), What: what, Fix: fix} }
		if (member.Kind == ast.KindMethodDeclaration) != (inherited.Flags&ast.SymbolFlagsMethod != 0) {
			return refuse("an inherited method replaced by a field, or a field replaced by a method", "keep the inherited member kind; use a different name for the new member")
		}
		if accessorMember(member) != accessorSymbol(inherited) {
			return refuse("an inherited data property replaced by an accessor, or an accessor replaced by data", "keep the inherited member kind; use another name for the new property")
		}
		if accessorMember(member) {
			ownGet, ownSet, baseGet, baseSet := false, false, false, false
			for _, candidate := range declaration.Members() {
				if candidate.Name() != nil && candidate.Name().Text() == member.Name().Text() && ast.HasSyntacticModifier(candidate, ast.ModifierFlagsStatic) == static {
					ownGet = ownGet || candidate.Kind == ast.KindGetAccessor
					ownSet = ownSet || candidate.Kind == ast.KindSetAccessor
				}
			}
			for _, candidate := range inherited.Declarations {
				baseGet = baseGet || candidate.Kind == ast.KindGetAccessor
				baseSet = baseSet || candidate.Kind == ast.KindSetAccessor
			}
			if (baseGet && !ownGet) || (baseSet && !ownSet) {
				return refuse("an accessor override that hides the inherited getter or setter", "override both halves of the inherited descriptor; delegate an unchanged half to super")
			}
			if member.Kind == ast.KindSetAccessor {
				for _, candidate := range inherited.Declarations {
					if candidate.Kind != ast.KindSetAccessor {
						continue
					}
					old := l.checker.GetSignatureFromDeclaration(candidate)
					next := l.checker.GetSignatureFromDeclaration(member)
					accepts := l.checker.GetTypeOfSymbol(old.Parameters()[0])
					override := l.checker.GetTypeOfSymbol(next.Parameters()[0])
					if !static {
						accepts = instantiateType(l.checker, accepts, l.typeMapperOf(candidate.Parent, base))
						override = instantiateType(l.checker, override, l.typeMapperOf(declaration, classType))
					}
					if !l.classAssignable(accepts, override) || l.widened(accepts, override, map[[2]*checker.Type]bool{}) != nil {
						return refuse("an accessor override that narrows a setter parameter (adamic/contravariant-override)", "accept the base setter's parameter type or a wider type; narrow it inside the setter")
					}
				}
			}
			if ownGet && (!l.classAssignable(own, previous) || l.widened(own, previous, map[[2]*checker.Type]bool{}) != nil) {
				return refuse("an accessor override with an unsafe read or write type (adamic/invariant-mutable)", "keep the inherited accessor type; narrow values inside the accessor")
			}
		}
		if member.Kind == ast.KindPropertyDeclaration || parameterProperty(member) {
			if !l.checker.IsReadonlySymbol(inherited) && (!l.classAssignable(previous, own) || !l.classAssignable(own, previous) || l.widened(previous, own, map[[2]*checker.Type]bool{}) != nil || l.widened(own, previous, map[[2]*checker.Type]bool{}) != nil) {
				return refuse("a mutable inherited field redeclared with a different type (adamic/invariant-mutable)", "keep the base field's type; narrow a local after reading it, or make the field readonly in the base")
			}
			if l.checker.IsReadonlySymbol(inherited) && (l.widened(own, previous, map[[2]*checker.Type]bool{}) != nil || !l.classAssignable(own, previous)) {
				return refuse("an inherited readonly field whose mutable contents are narrowed (adamic/invariant-mutable)", "keep mutable contents at the base type, or make the contents readonly in the base too")
			}
			if l.checker.IsReadonlySymbol(inherited) && !ast.HasSyntacticModifier(member, ast.ModifierFlagsReadonly) {
				return refuse("a readonly inherited field redeclared mutable", "keep the inherited field readonly")
			}
			from, okFrom := l.representation(previous)
			to, okTo := l.representation(own)
			if checkABI && (!okFrom || !okTo || from != to) {
				return l.notYet(member, "an inherited field override with a different native representation")
			}
		}
		if member.Kind != ast.KindMethodDeclaration {
			continue
		}
		oldSignatures := l.checker.GetSignaturesOfType(previous, checker.SignatureKindCall)
		newSignatures := l.checker.GetSignaturesOfType(own, checker.SignatureKindCall)
		if len(oldSignatures) != 1 || len(newSignatures) != 1 {
			return l.notYet(member, "an overloaded override")
		}
		old, next := oldSignatures[0], newSignatures[0]
		if len(old.Parameters()) != len(next.Parameters()) {
			return l.notYet(member, "an override with a different parameter count; keep the base method's parameter count")
		}
		for index, parameter := range old.Parameters() {
			accepts := l.checker.GetTypeOfSymbol(parameter)
			override := l.checker.GetTypeOfSymbol(next.Parameters()[index])
			a, knownA := l.overrideParameterRepresentation(parameter)
			b, knownB := l.overrideParameterRepresentation(next.Parameters()[index])
			if checkABI && (!knownA || !knownB || a != b) {
				return l.notYet(member, "an override with a different native representation for parameter "+strconv.Quote(next.Parameters()[index].Name)+"; keep the base method's parameter form")
			}
			if !l.classAssignable(accepts, override) || l.widened(accepts, override, map[[2]*checker.Type]bool{}) != nil {
				return refuse("an override that narrows a method parameter (adamic/contravariant-override)", "accept the base method's parameter type or a wider type; narrow it inside the method")
			}
		}
		oldResult := l.checker.GetReturnTypeOfSignature(old)
		newResult := l.checker.GetReturnTypeOfSignature(next)
		a, knownA := l.overrideResultRepresentation(oldResult)
		b, knownB := l.overrideResultRepresentation(newResult)
		if checkABI && (!knownA || !knownB || a != b) {
			return l.notYet(member, "an override with a different native result representation; keep the base method's result form")
		}
		if !l.classAssignable(newResult, oldResult) || l.widened(newResult, oldResult, map[[2]*checker.Type]bool{}) != nil {
			return refuse("an override that widens its return type", "return the base method's result type or a subtype")
		}
	}
	return nil
}

// Match signature lowering, including the incoming optional form of a defaulted parameter.
// The signature's symbol carries the instantiated type; its declaration carries the default.
func (l *lowering) overrideParameterRepresentation(parameter *ast.Symbol) (ir.Type, bool) {
	if len(parameter.Declarations) != 1 || parameter.Declarations[0].Kind != ast.KindParameter {
		return 0, false
	}
	declaration := parameter.Declarations[0]
	declared := declaration.AsParameterDeclaration()
	if declared.DotDotDotToken != nil {
		return 0, false
	}
	name := declaration.Name()
	if name.Kind == ast.KindArrayBindingPattern || name.Kind == ast.KindObjectBindingPattern {
		return ir.Object, declared.Initializer == nil && declared.QuestionToken == nil
	}
	representation, known := l.representation(l.checker.GetTypeOfSymbol(parameter))
	if declared.Initializer != nil || declared.QuestionToken != nil {
		representation = ir.Maybe(representation)
	}
	return representation, known
}

// Named methods returning void or never have no C result, as signature lowering does.
func (l *lowering) overrideResultRepresentation(result *checker.Type) (ir.Type, bool) {
	if result.Flags()&(checker.TypeFlagsVoid|checker.TypeFlagsNever) != 0 {
		return 0, true
	}
	return l.representation(result)
}

// Constructors initialize an already allocated object. A separate allocator fixes its dynamic
// identity before even the base constructor runs, so base method calls can dispatch dynamically.
func (l *lowering) inheritanceConstructor(index int, declaration *ast.Node) error {
	instance := l.instance
	var constructor *ast.Node
	for _, member := range declaration.Members() {
		if member.Kind == ast.KindConstructor {
			constructor = member
		}
	}
	instance.initializer = len(l.result.Functions)
	initializer := instance.initializer
	l.result.Functions = append(l.result.Functions, ir.Function{Name: l.result.Functions[index].Name + "_initialize"})
	this := l.thisLocal(initializer)
	outerThis, outerIndex, outerFunction := l.this, l.functionIndex, l.function
	context := l.result.Functions[initializer]
	l.this, l.functionIndex, l.function = this, initializer, &context
	defer func() { l.this, l.functionIndex, l.function = outerThis, outerIndex, outerFunction }()
	if constructor != nil {
		if err := l.signature(initializer, constructor, this); err != nil {
			return err
		}
		l.result.Functions[initializer].Parameters = append([]int{this}, l.result.Functions[initializer].Parameters...)
	} else {
		l.result.Functions[initializer].Parameters = []int{this}
		if instance.base != nil {
			for _, parameter := range l.result.Functions[instance.base.initializer].Parameters[1:] {
				local := len(l.result.Locals)
				incoming := l.result.Locals[parameter]
				incoming.Function, incoming.Captured, incoming.Borrowed = initializer, false, false
				l.result.Locals = append(l.result.Locals, incoming)
				l.result.Functions[initializer].Parameters = append(l.result.Functions[initializer].Parameters, local)
			}
		}
	}
	l.result.Functions[initializer].Receiver = true
	if constructor == nil && instance.base != nil {
		l.result.Functions[initializer].RestElement = l.result.Functions[instance.base.initializer].RestElement
		l.result.Functions[initializer].ForwardsArguments = instance.base.initializer + 1
	}
	// The layout contains inherited fields first, but only this class's initializers run here.
	fields := append([]ir.Field{}, l.result.Classes[instance.class-1].Fields...)
	for _, member := range classMembersWithParameters(declaration) {
		if member.Kind != ast.KindPropertyDeclaration && !parameterProperty(member) {
			continue
		}
		if ast.HasSyntacticModifier(member, ast.ModifierFlagsAmbient|ast.ModifierFlagsAbstract) {
			return l.notYet(member, "a declare or abstract class field")
		}
		if ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic) {
			continue
		}
		if !ast.IsIdentifier(member.Name()) && member.Name().Kind != ast.KindPrivateIdentifier {
			return l.notYet(member, "a field with a computed name")
		}
		of, err := l.typeOf(member.Name())
		if err != nil {
			return err
		}
		if slotless(of) {
			return l.notYet(member, "a field of type "+l.checker.TypeToString(l.checker.GetTypeAtLocation(member.Name())))
		}
		field := ir.Field{Name: l.fieldName(member.Name()), Value: zeroValue(of), Private: member.Name().Kind == ast.KindPrivateIdentifier, Uninitialized: l.uninitializedDeclaration(member) || (member.Kind == ast.KindPropertyDeclaration && l.lazyAssertionInitializer(member.AsPropertyDeclaration().Initializer))}
		// An uninitialized reference still has its declared representation for the shape bitmap.
		if of.IsReference() {
			field.Value = ir.Undefined{Of: of}
		}
		found := false
		for i := range fields {
			if fields[i].Name == field.Name {
				fields[i] = field
				found = true
				break
			}
		}
		if !found {
			fields = append(fields, field)
		}
	}
	l.result.Classes[instance.class-1].Fields = fields
	if instance.base == nil {
		initialized, err := l.fieldInitializers(declaration, this)
		if err != nil {
			return err
		}
		l.result.Functions[initializer].Body = initialized
	}
	if constructor != nil {
		instance.constructing = true
		defer func() { instance.constructing = false }()
		var returnValue *ast.Node
		var returns ast.Visitor
		returns = func(node *ast.Node) bool {
			if ast.IsFunctionLike(node) {
				return false
			}
			if node.Kind == ast.KindReturnStatement && node.AsReturnStatement().Expression != nil {
				returnValue = node
				return true
			}
			return node.ForEachChild(returns)
		}
		constructor.Body().ForEachChild(returns)
		if returnValue != nil {
			return l.notYet(returnValue, "a constructor returning a replacement value")
		}
		state := uint8(0)
		if instance.base != nil {
			var err error
			state, err = l.prepareSuper(constructor, initializer)
			if err != nil {
				return err
			}
		}

		outerUnset := l.unsetUntil
		l.unsetUntil = lastFieldAssignment(declaration, constructor)
		err := l.lowerFunction(initializer, constructor, this)
		l.unsetUntil = outerUnset
		if err != nil {
			return err
		}
		if state&superUninitialized != 0 {
			l.result.Functions[initializer].Body = append(l.result.Functions[initializer].Body, l.superEnd())
		}
	} else if instance.base != nil {
		arguments := []ir.Expression{}
		for _, parameter := range l.result.Functions[initializer].Parameters {
			arguments = append(arguments, ir.Read{Local: parameter, Of: l.result.Locals[parameter].Type})
		}
		l.result.Functions[initializer].Body = []ir.Statement{ir.Evaluate{Value: ir.Call{Function: instance.base.initializer, Arguments: arguments, ForwardCount: true, RestPacked: true}}}
		initialized, err := l.fieldInitializers(declaration, this)
		if err != nil {
			return err
		}
		l.result.Functions[initializer].Body = append(l.result.Functions[initializer].Body, initialized...)
	}
	if instance.base == nil && !instance.hasDescendants {
		// Keep creation and writes in one function when no derived constructor needs this
		// initializer. Freshness then knows this is new at each write, not just at return.
		body := l.result.Functions[initializer]
		for local := range l.result.Locals {
			if l.result.Locals[local].Function == initializer {
				l.result.Locals[local].Function = index
			}
		}
		wrapper := l.result.Functions[index]
		wrapper.Parameters = append([]int{}, body.Parameters[1:]...)
		wrapper.ArgumentsCount = body.ArgumentsCount
		wrapper.ForwardsArguments = body.ForwardsArguments
		wrapper.RestElement = body.RestElement
		wrapper.Body = append([]ir.Statement{ir.Declare{Local: this, Value: ir.ObjectLiteral{Fields: fields, Class: instance.class, Methods: instance.methodList()}}}, body.Body...)
		wrapper.Body = append(wrapper.Body, ir.Return{Value: ir.Read{Local: this, Of: ir.Object}})
		l.result.Functions[index] = wrapper
		l.result.Functions[initializer] = ir.Function{Name: body.Name}
		return nil
	}
	// The public constructor owns its object, including when an initializer throws.
	wrapper := l.result.Functions[index]
	wrapper.ForwardsArguments = initializer + 1
	wrapper.RestElement = l.result.Functions[initializer].RestElement
	arguments := []ir.Expression{}
	object := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "this", Type: ir.Object, Function: index})
	l.noteLocal(object, l.classType, declaration.Name())
	arguments = append(arguments, ir.Read{Local: object, Of: ir.Object})
	for _, parameter := range l.result.Functions[initializer].Parameters[1:] {
		incoming := l.result.Locals[parameter]
		incoming.Function, incoming.Captured, incoming.Borrowed = index, false, false
		local := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, incoming)
		wrapper.Parameters = append(wrapper.Parameters, local)
		arguments = append(arguments, ir.Read{Local: local, Of: incoming.Type})
	}
	wrapper.Body = []ir.Statement{
		ir.Declare{Local: object, Value: ir.ObjectLiteral{Fields: fields, Class: instance.class, Methods: instance.methodList()}},
		ir.Evaluate{Value: ir.Call{Function: initializer, Arguments: arguments, ForwardCount: true, RestPacked: true}},
		ir.Return{Value: ir.Read{Local: object, Of: ir.Object}},
	}
	l.result.Functions[index] = wrapper
	return nil
}

func (l *lowering) fieldInitializers(declaration *ast.Node, this int) ([]ir.Statement, error) {
	statements := []ir.Statement{}
	available := map[string]bool{}
	if l.instance.base != nil {
		for _, field := range l.result.Classes[l.instance.base.class-1].Fields {
			available[field.Name] = true
		}
	}
	resets, err := l.parameterPropertyResets(declaration, this, available)
	if err != nil {
		return nil, err
	}
	statements = append(statements, resets...)
	for _, member := range declaration.Members() {
		if member.Kind != ast.KindPropertyDeclaration || ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic) {
			continue
		}
		of, err := l.typeOf(member.Name())
		if err != nil {
			return nil, err
		}
		if l.uninitializedDeclaration(member) {
			value := zeroValue(of)
			if of.IsReference() {
				value = ir.Undefined{Of: of}
			}
			statements = append(statements, ir.SetProperty{Object: ir.Read{Local: this, Of: ir.Object}, Name: l.fieldName(member.Name()), Value: value, Uninitialized: true, Site: l.writeSite(declaration.Name())})
			available[l.fieldName(member.Name())] = true
			continue
		}

		if initializer := member.AsPropertyDeclaration().Initializer; l.lazyAssertionInitializer(initializer) {
			if err := l.initializerReads(initializer, available); err != nil {
				return nil, err
			}
			prefix, present, value, err := l.lazyAssertion(initializer, of)
			if err != nil {
				return nil, err
			}
			empty := ir.Expression(zeroValue(of))
			if of.IsReference() {
				empty = ir.Undefined{Of: of}
			}
			statements = append(statements, prefix...)
			statements = append(statements, ir.SetProperty{Object: ir.Read{Local: this, Of: ir.Object}, Name: l.fieldName(member.Name()), Value: empty, Uninitialized: true, Site: l.writeSite(declaration.Name())}, ir.If{Condition: present, Then: []ir.Statement{ir.SetProperty{Object: ir.Read{Local: this, Of: ir.Object}, Name: l.fieldName(member.Name()), Value: value, Site: l.writeSite(declaration.Name())}}})
			available[l.fieldName(member.Name())] = true
			continue
		}
		value := zeroValue(of)
		if member.AsPropertyDeclaration().Initializer != nil {
			if err := l.initializerReads(member.AsPropertyDeclaration().Initializer, available); err != nil {
				return nil, err
			}
			value, err = l.expression(member.AsPropertyDeclaration().Initializer)
			if err != nil {
				return nil, err
			}
			value = fit(value, of)
		} else if of.IsReference() {
			value = ir.Undefined{Of: of}
		}
		statements = append(statements, ir.SetProperty{Object: ir.Read{Local: this, Of: ir.Object}, Name: l.fieldName(member.Name()), Value: value, Site: l.writeSite(declaration.Name())})
		available[l.fieldName(member.Name())] = true
	}
	return statements, nil
}

func (l *lowering) superCall(node *ast.Node) (ir.Expression, error) {
	if l.instance == nil || l.instance.base == nil || l.this < 0 {
		return nil, l.notYet(node, "super outside a derived constructor")
	}
	arguments := []ir.Expression{ir.Read{Local: l.this, Of: ir.Object}}
	for _, argument := range nodesOf(node.AsCallExpression().Arguments) {
		value, err := l.expression(argument)
		if err != nil {
			return nil, err
		}
		arguments = append(arguments, value)
	}
	return ir.Call{Function: l.instance.base.initializer, Arguments: arguments}, nil
}

func (l *lowering) superStatement(node *ast.Node) ([]ir.Statement, error) {
	call, err := l.superCall(node)
	if err != nil {
		return nil, err
	}
	statements := []ir.Statement{}
	if l.instance.superStates[node]&superInitialized != 0 {
		// JavaScript constructs another base object before rejecting a second binding.
		// Do not overwrite the already initialized object's fields on this path.
		base := call.(ir.Call)
		second := ir.Call{Function: l.instance.base.constructor, Arguments: base.Arguments[1:], Returns: ir.Object}
		statements = append(statements, ir.If{Condition: ir.Read{Local: l.instance.superReady, Of: ir.Boolean}, Then: []ir.Statement{ir.Evaluate{Value: second}, l.superError("Super constructor may only be called once")}})
	}
	statements = append(statements, ir.Evaluate{Value: call}, ir.Assign{Local: l.instance.superReady, Value: ir.BooleanConstant{Value: true}})
	// Fields run only once super has returned, and before the next derived-body statement.
	declaration := l.classNode.Parent
	initialized, err := l.fieldInitializers(declaration, l.this)
	if err != nil {
		return nil, err
	}
	statements = append(statements, initialized...)
	assigned, err := l.parameterPropertyStores(declaration, l.this)
	return append(statements, assigned...), err
}

func (l *lowering) classInstanceOf(node *ast.Node) (ir.Expression, error) {
	binary := node.AsBinaryExpression()
	declaration := l.classes[l.symbol(ast.SkipParentheses(binary.Right))]
	if declaration == nil {
		return nil, l.notYet(node, "instanceof against a value that isn't a declared class")
	}
	identity := 0
	if len(declaration.TypeParameters()) > 0 {
		// JavaScript erases type arguments for instanceof, even when native layouts differ.
		identity = l.classIdentity(declaration)
	} else {
		instance, err := l.instantiate(declaration, l.checker.GetTypeAtLocation(declaration.Name()), node)
		if err != nil {
			return nil, err
		}
		identity = instance.class
	}
	value, err := l.expression(binary.Left)
	if err != nil {
		return nil, err
	}
	return ir.InstanceOf{Value: value, Class: identity}, nil
}

// Finish calls after lowering discovers every instantiated descendant. The analyses see all
// implementations; code generation still uses the receiver's single dynamic method table.
func (l *lowering) finishClassCalls() {
	l.result.MethodTargets = map[int][]int{}
	for _, class := range l.result.Classes {
		for slot, implementation := range class.Methods {
			for parent := &class; parent != nil; {
				if slot < len(parent.Methods) {
					function := parent.Methods[slot]
					if !slices.Contains(l.result.MethodTargets[function], implementation) {
						l.result.MethodTargets[function] = append(l.result.MethodTargets[function], implementation)
					}
				}
				if parent.Base == 0 {
					break
				}
				parent = &l.result.Classes[parent.Base-1]
			}
		}
	}
}

func (l *lowering) noteInheritance(modules []*ast.SourceFile) {
	l.derivedAncestors = map[*ast.Symbol]bool{}
	for _, module := range modules {
		var visit ast.Visitor
		visit = func(node *ast.Node) bool {
			if node.Kind == ast.KindClassDeclaration && node.Name() != nil {
				typ := l.checker.GetTypeAtLocation(node.Name())
				for _, base := range l.checker.GetBaseTypes(typ) {
					l.derivedAncestors[base.Symbol()] = true
				}
			}
			return node.ForEachChild(visit)
		}
		module.AsNode().ForEachChild(visit)
	}
}

// A class view needs nominal ancestry, even when TypeScript's structural relation accepts two
// unrelated classes or a plain object. Otherwise a virtual call would trust a table that isn't there.
func (l *lowering) classViewRefusal(node *ast.Node) error {
	if !viewSite(node) || node.Kind == ast.KindParenthesizedExpression {
		return nil
	}
	if parent := node.Parent; parent != nil && parent.Kind == ast.KindVariableDeclaration && parent.Name().Kind == ast.KindArrayBindingPattern {
		return l.classDestructuredView(node, parent.Name())
	}
	target := l.checker.GetContextualType(node, checker.ContextFlagsNone)
	if target == nil {
		return nil
	}
	// Fresh literals are built as their contextual type; their explicit values are
	// checked at their own sites. Spreads still need the whole inherited shape checked.
	if node.Kind == ast.KindObjectLiteralExpression || node.Kind == ast.KindArrayLiteralExpression {
		spread := false
		for _, child := range literalParts(node) {
			if child.Kind == ast.KindSpreadAssignment || child.Kind == ast.KindSpreadElement {
				spread = true
			}
		}
		if !spread && !l.nominalLiteralTarget(target) {
			return nil
		}
	}
	source := l.checker.GetTypeAtLocation(node)
	mismatch := l.nominalMismatch(source, target, map[[2]*checker.Type]bool{})
	if mismatch == nil {
		return nil
	}
	target = mismatch
	return &Refused{Where: l.program.Where(node), What: "a value without nominal ancestry seen as " + l.checker.TypeToString(target), Fix: "construct that class or a subclass; use an interface for structural values (adamic/nominal-class)"}
}

func (l *lowering) nominalAncestor(source, target *checker.Type, seen map[[2]*checker.Type]bool) bool {
	if source.Flags()&checker.TypeFlagsTypeParameter != 0 {
		if constraint := l.checker.GetBaseConstraintOfType(source); constraint != nil {
			source = constraint
		}
	}
	if weak := l.weakTarget(source); weak != nil {
		source = weak
	}
	if !isClassInstance(source) {
		return false
	}
	if source.Symbol() == target.Symbol() {
		from, to := l.checker.GetTypeArguments(source), l.checker.GetTypeArguments(target)
		if !l.sameClassArguments(from, to) {
			return false
		}
		for index := range from {
			if !l.enumAssignable(from[index], to[index]) || !l.enumAssignable(to[index], from[index]) || l.nominalMismatch(from[index], to[index], seen) != nil || l.nominalMismatch(to[index], from[index], seen) != nil {
				return false
			}
		}
		return true
	}
	for _, base := range l.classBases(source) {
		if l.nominalAncestor(base, target, seen) {
			return true
		}
	}
	return false
}

// Initializers may read fields already initialized, including the base's after super. A future
// field would hold undefined despite its declared type; a method may read future derived fields.
func (l *lowering) initializerReads(node *ast.Node, available map[string]bool) error {
	seen := map[*ast.Node]bool{}
	var examine func(*ast.Node, []string) error
	examine = func(body *ast.Node, path []string) error {
		if body == nil || seen[body] {
			return nil
		}
		seen[body] = true
		var refused error
		var visit ast.Visitor
		visit = func(child *ast.Node) bool {
			if refused != nil {
				return true
			}
			if ast.IsPartOfTypeNode(child) {
				return false
			}
			if child.Kind == ast.KindPropertyAccessExpression {
				object := ast.SkipParentheses(child.AsPropertyAccessExpression().Expression)
				if object.Kind == ast.KindThisKeyword || object.Kind == ast.KindSuperKeyword {
					symbol := l.checker.GetSymbolAtLocation(child.Name())
					if object.Kind == ast.KindThisKeyword && child.Name().Kind != ast.KindPrivateIdentifier {
						symbol = l.checker.GetPropertyOfType(l.classType, child.Name().Text())
					}
					if symbol != nil {
						for _, member := range symbol.Declarations {
							step := child.Name().Text()
							if member.Parent != nil && member.Parent.Name() != nil {
								step = member.Parent.Name().Text() + "." + step
							}
							next := append(append([]string{}, path...), step)
							if member.Kind == ast.KindMethodDeclaration || member.Kind == ast.KindGetAccessor {
								refused = examine(member.Body(), next)
							} else if (member.Kind == ast.KindPropertyDeclaration || parameterProperty(member)) && !available[l.fieldName(child.Name())] {
								refused = &Refused{Where: l.program.Where(child), What: "a field initializer reading an uninitialized field through " + strings.Join(next, " -> "), Fix: "declare the field it reads earlier, or initialize it in the constructor after super and all required fields are set"}
							}
							if refused != nil {
								return true
							}
						}
						return false
					}
				}
			}
			if child.Kind == ast.KindThisKeyword || child.Kind == ast.KindSuperKeyword {
				refused = &Refused{Where: l.program.Where(child), What: "this in a field initializer before the fields it reads are initialized", Fix: "declare the field it reads earlier, or initialize it in the constructor after super and all required fields are set"}
				return true
			}
			return child.ForEachChild(visit)
		}
		visit(body)
		return refused
	}
	return examine(node, nil)
}

// Private names with the same spelling in a base and a derived class are separate JavaScript slots,
// so each is qualified by the class that declares it (privateName), the same spelling memberKey gives
// its definition, for fields, methods, accessors and statics alike.
func (l *lowering) fieldName(name *ast.Node) string {
	if name.Kind != ast.KindPrivateIdentifier {
		return name.Text()
	}
	if declaring := l.declaringClass(name); declaring != nil {
		return l.privateName(name.Text(), declaring)
	}
	return name.Text()
}

// Assignment to a nominal class also requires ancestry; structural compatibility alone cannot
// provide the dynamic table an override's caller expects.
func (l *lowering) classAssignable(from, to *checker.Type) bool {
	return l.checker.IsTypeAssignableTo(from, to) && l.nominalMismatch(from, to, map[[2]*checker.Type]bool{}) == nil
}

// Follow nominal class slots inside structural containers too. A plain object inside A[] lacks
// the same method table as a plain object assigned directly to A. Mutable slots need both views.
func (l *lowering) nominalMismatch(from, to *checker.Type, seen map[[2]*checker.Type]bool) *checker.Type {
	if from == nil || to == nil || from == to || from.Flags()&(checker.TypeFlagsNever|checker.TypeFlagsUndefined) != 0 || seen[[2]*checker.Type{from, to}] {
		return nil
	}
	seen[[2]*checker.Type{from, to}] = true
	if from.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range from.Types() {
			if found := l.nominalMismatch(member, to, seen); found != nil {
				return found
			}
		}
		return nil
	}
	if to.Flags()&checker.TypeFlagsUnion != 0 {
		var failure *checker.Type
		for _, member := range to.Types() {
			if !l.checker.IsTypeAssignableTo(from, member) {
				continue
			}
			if found := l.nominalMismatch(from, member, seen); found != nil {
				failure = found
			} else {
				return nil
			}
		}
		return failure
	}
	if weak := l.weakTarget(from); weak != nil {
		from = weak
	}
	if weak := l.weakTarget(to); weak != nil {
		to = weak
	}
	if from.Flags()&checker.TypeFlagsTypeParameter != 0 {
		if constraint := l.checker.GetBaseConstraintOfType(from); constraint != nil {
			return l.nominalMismatch(constraint, to, seen)
		}
		return nil
	}
	if l.isStaticType(to) {
		wanted := l.staticClass(to, nil)
		actual := l.staticClass(from, nil)
		for actual != nil {
			if actual == wanted {
				return nil
			}
			actual = l.staticBase(actual)
		}
		return to
	}
	if isClassInstance(to) {
		if symbol := to.Symbol(); symbol != nil && len(symbol.Declarations) > 0 && load.IsPrelude(ast.GetSourceFileOfNode(symbol.Declarations[0])) {
			return nil
		}
		if !l.nominalAncestor(from, to, seen) {
			return to
		}
		return nil
	}
	if !l.structured(from) || !l.structured(to) {
		return nil
	}
	fromSignatures := l.checker.GetSignaturesOfType(from, checker.SignatureKindCall)
	toSignatures := l.checker.GetSignaturesOfType(to, checker.SignatureKindCall)
	if len(fromSignatures) > 0 && len(toSignatures) > 0 {
		parameters := toSignatures[0].Parameters()
		if l.censusNeverRestSignature(toSignatures[0]) {
			parameters = nil
		}
		for index, parameter := range parameters {
			if index >= len(fromSignatures[0].Parameters()) {
				break
			}
			if found := l.nominalMismatch(l.checker.GetTypeOfSymbol(parameter), l.checker.GetTypeOfSymbol(fromSignatures[0].Parameters()[index]), seen); found != nil {
				return found
			}
		}
		return l.nominalMismatch(l.checker.GetReturnTypeOfSignature(fromSignatures[0]), l.checker.GetReturnTypeOfSignature(toSignatures[0]), seen)
	}
	for _, target := range l.containers(to) {
		for _, source := range l.containers(from) {
			if !l.sameContainer(source, target) {
				continue
			}
			fromArguments, toArguments := l.checker.GetTypeArguments(source), l.checker.GetTypeArguments(target)
			mutable := !l.isLibraryType(target, "ReadonlyArray", "ReadonlyMap", "ReadonlySet") && !(checker.IsTupleType(target) && target.TargetTupleType().IsReadonly())
			for index := 0; index < len(fromArguments) && index < len(toArguments); index++ {
				if found := l.nominalMismatch(fromArguments[index], toArguments[index], seen); found != nil {
					return found
				}
				if mutable {
					if found := l.nominalMismatch(toArguments[index], fromArguments[index], seen); found != nil {
						return found
					}
				}
			}
		}
	}
	if len(l.containers(to)) > 0 {
		return nil
	}
	for _, property := range l.checker.GetPropertiesOfType(to) {
		if property.Flags&ast.SymbolFlagsMethod != 0 {
			continue
		}
		inside := l.checker.GetPropertyOfType(from, property.Name)
		if inside == nil {
			continue
		}
		source, target := l.checker.GetTypeOfSymbol(inside), l.checker.GetTypeOfSymbol(property)
		if found := l.nominalMismatch(source, target, seen); found != nil {
			return found
		}
		if !l.checker.IsReadonlySymbol(property) {
			if found := l.nominalMismatch(target, source, seen); found != nil {
				return found
			}
		}
	}
	return nil
}

// An inferred destructuring context can be the union of the tuple's elements. Compare the
// positional values with their bound names instead of treating that union as a writable array.
func (l *lowering) classDestructuredView(node, pattern *ast.Node) error {
	own := l.checker.GetTypeAtLocation(node)
	elements := l.checker.GetTypeArguments(own)
	tuple := checker.IsTupleType(own)
	for index, binding := range pattern.AsBindingPattern().Elements.Nodes {
		if binding.Kind == ast.KindOmittedExpression || binding.Name() == nil {
			continue
		}
		if !tuple {
			index = 0
		}
		if index >= len(elements) {
			continue
		}
		target := l.checker.GetTypeAtLocation(binding.Name())
		if mismatch := l.nominalMismatch(elements[index], target, map[[2]*checker.Type]bool{}); mismatch != nil {
			return &Refused{Where: l.program.Where(binding), What: "a destructured value without nominal ancestry seen as " + l.checker.TypeToString(mismatch), Fix: "construct that class or a subclass; use an interface for structural values (adamic/nominal-class)"}
		}
	}
	return nil
}

// The checker mangles private symbol names; the IR qualifies them by class ID. Cycle proofs
// must match the same declaration in both names, including inherited and generic private slots.
func (l *lowering) cycleFieldMatches(holder *checker.Type, field, written string) bool {
	if field == written {
		return true
	}
	property := l.checker.GetPropertyOfType(holder, field)
	if property == nil || len(property.Declarations) != 1 {
		return false
	}
	name := property.Declarations[0].Name()
	if name == nil || name.Kind != ast.KindPrivateIdentifier {
		return false
	}
	if class := property.Declarations[0].Parent; class != nil && class.Kind == ast.KindClassDeclaration {
		return written == l.privateName(name.Text(), class)
	}
	return written == name.Text()
}

func (l *lowering) cycleFieldName(field *ast.Symbol) string {
	if len(field.Declarations) == 1 {
		if name := field.Declarations[0].Name(); name != nil && name.Kind == ast.KindPrivateIdentifier {
			return name.Text()
		}
	}
	return field.Name
}

// All monomorphizations of a source class have one erased identity. An identity-only
// descriptor lets instanceof name a generic class before any concrete instance is made.
func (l *lowering) classDefinition(declaration *ast.Node) int {
	for key, instance := range l.instances {
		if l.classKeyMatches(key, declaration) {
			return l.result.Classes[instance.class-1].Definition
		}
	}
	return len(l.result.Classes) + 1
}

func (l *lowering) classIdentity(declaration *ast.Node) int {
	definition := l.classDefinition(declaration)
	for index, class := range l.result.Classes {
		if class.Definition == definition {
			return index + 1
		}
	}
	identity := len(l.result.Classes) + 1
	l.result.Classes = append(l.result.Classes, ir.Class{Name: declaration.Name().Text() + "_identity", Definition: definition, Constructor: -1})
	if l.instances == nil {
		l.instances = map[string]*instance{}
	}
	key := l.classKeyPrefix(declaration) + ",identity"
	l.instances[key] = &instance{class: identity, constructor: -1, initializer: -1}
	return identity
}

// An inherited method's receiver can be a descendant with different type arguments.
// Find the declaration's actual instantiated view instead of substituting by position.
func (l *lowering) classView(proven *checker.Type, declaration *ast.Node) *checker.Type {
	if proven.Flags()&checker.TypeFlagsTypeParameter != 0 {
		if constraint := l.checker.GetBaseConstraintOfType(proven); constraint != nil {
			proven = constraint
		}
	}
	if weak := l.weakTarget(proven); weak != nil {
		proven = weak
	}
	if proven.Symbol() == l.symbol(declaration.Name()) {
		return proven
	}
	for _, base := range l.classBases(proven) {
		if found := l.classView(base, declaration); found != nil {
			return found
		}
	}
	return nil
}

// The checker exposes generic bases on the declaration. Substitute the receiver's
// actual arguments before choosing a native base layout or proving nominal ancestry.
func (l *lowering) classBases(proven *checker.Type) []*checker.Type {
	target := proven
	if proven.ObjectFlags()&checker.ObjectFlagsReference != 0 && proven.Target() != nil {
		target = proven.Target()
	}
	bases := l.checker.GetBaseTypes(target)
	declaration := l.classNodeFor(proven)
	if declaration == nil || declaration.Kind != ast.KindClassDeclaration {
		return bases
	}
	mapper := l.typeMapperOf(declaration, proven)
	if mapper == nil {
		return bases
	}
	concrete := make([]*checker.Type, len(bases))
	for index, base := range bases {
		concrete[index] = instantiateType(l.checker, base, mapper)
	}
	return concrete
}

func literalParts(node *ast.Node) []*ast.Node {
	if node.Kind == ast.KindObjectLiteralExpression {
		return node.AsObjectLiteralExpression().Properties.Nodes
	}
	return node.AsArrayLiteralExpression().Elements.Nodes
}

func (l *lowering) nominalLiteralTarget(proven *checker.Type) bool {
	if weak := l.weakTarget(proven); weak != nil {
		proven = weak
	}
	if isClassInstance(proven) {
		return true
	}
	if proven.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range proven.Types() {
			if l.nominalLiteralTarget(member) {
				return true
			}
		}
	}
	return false
}

lower.go:
// Package lower turns a checked program into Adamic's IR.
//
// Stage 0 lowers a little and refuses the rest. Every construct it can't lower yet is an error
// naming the construct and where it is, never a skip: a compiler that drops a statement it doesn't
// understand produces a program that looks right and isn't, which is the one thing Adamic must
// never do.
package lower

import (
	"context"
	"fmt"
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
	"path/filepath"
)

// Lower lowers a checked program from one entry, in ESM evaluation order.
func Lower(ctx context.Context, program *load.Program) (*ir.Program, error) {
	files := program.Files()
	if len(files) != 1 {
		return nil, fmt.Errorf("lower: stage 0 compiles a program from one entry file, got %d", len(files))
	}
	entry := files[0]
	// Stage 0 checks single-threaded, so one checker answers for every file.
	typeChecker, release := program.Checker(ctx, entry)
	defer release()

	lowering := &lowering{program: program, checker: typeChecker, result: &ir.Program{}, this: -1, functionIndex: -1}
	// The base name only, so the same program emits the same C on every machine.
	lowering.result.Source = filepath.Base(program.FileName(entry))
	modules, err := lowering.moduleOrder(entry)
	if err != nil {
		return nil, err
	}
	lowering.noteInheritance(modules)
	if err := lowering.enumInitialization(modules); err != nil {
		return nil, err
	}
	lowering.noteAccessorNames(modules)
	lowering.noteOmittedOptionals(modules)
	if err := lowering.namespaceInitialization(modules); err != nil {
		return nil, err
	}
	for _, module := range modules {
		if err := lowering.refuse(module); err != nil {
			return nil, err
		}
	}
	// Link every declaration before lowering any function body, including across back edges.
	var declarations []*ast.Node
	for _, module := range modules {
		declarations = append(declarations, module.Statements.Nodes...)
	}
	if err := lowering.declareModule(declarations); err != nil {
		return nil, err
	}
	for _, module := range modules {
		body, err := lowering.statements(module.Statements.Nodes)
		if err != nil {
			return nil, err
		}
		lowering.result.Main = append(lowering.result.Main, body...)
	}
	if lowering.unlowerable != nil {
		return nil, lowering.unlowerable
	}
	lowering.result.Main = append(lowering.forwarderValues, lowering.result.Main...)
	lowering.finishClassCalls()
	if err := lowering.finishAccessors(); err != nil {
		return nil, err
	}
	if err := lowering.exceptions(); err != nil {
		return nil, err
	}
	if err := lowering.checkAccessorSpreads(); err != nil {
		return nil, err
	}
	if err := lowering.findCycles(modules); err != nil {
		return nil, err
	}
	readiness(lowering.result)
	borrow(lowering.result)
	counters(lowering.result)
	return lowering.result, nil
}

type lowering struct {
	// V2 retains exact logical producer types for union member certification.
	untaggedCallableTargets map[ir.ViewContractID]*checker.Type

	program *load.Program
	checker *checker.Checker
	result  *ir.Program

	// cyclicModules keeps unresolved reads checked throughout a cyclic graph.
	cyclicModules     bool
	provenModuleReads map[*ast.Node]bool
	cycleReadFindings []Finding

	// strings indexes result.Strings, so a constant used twice is stored once.
	strings map[string]int

	// locals maps each variable's symbol to its index in result.Locals.
	locals map[*ast.Symbol]int

	// functions maps each function declaration's symbol to its index in result.Functions.
	functions map[*ast.Symbol]int

	// function is the function being lowered, or nil for the module's top level.
	function *ir.Function

	// this is the local this is in a method or constructor, or -1.
	this int

	// functionIndex is the function being lowered, -1 for the module's top level, and closures the
	// closures being lowered, outermost first, each inside the one before.
	functionIndex int
	closures      []int

	// classes maps each module class's symbol to its declaration, and instances each instantiation
	// already lowered (class.go).
	// omittedOptionals is every optional property some object literal typed by its context leaves out:
	// that object has no slot for it (class.go's absentOptionalWrite).
	omittedOptionals map[*ast.Symbol]bool
	classes          map[*ast.Symbol]*ast.Node
	statics          map[*ast.Symbol]*instance
	staticGlobals    map[*ast.Symbol]int
	instances        map[string]*instance
	derivedAncestors map[*ast.Symbol]bool

	// privateOwners numbers each class that declares a private name, in the order first met, to
	// qualify its private members' names (privateName).
	privateOwners map[*ast.Node]int

	// instance is the class instantiation being lowered, if any.
	instance *instance

	// substitution is what each type parameter stands for in the instantiation being lowered.
	substitution map[*checker.Type]ir.Type

	// unlowerable is the first construct found not lowerable somewhere that can't return an error.
	unlowerable error

	// alwaysUndefined are parameters that only ever receive undefined, whatever the checker calls
	// their type: the first of an Array.from callback's (from.go). Each is a reference that's always
	// missing.
	alwaysUndefined map[*ast.Symbol]bool

	// signed are the functions whose signatures are written and whose bodies aren't lowered yet, by
	// index, each with what its body still needs (signature).
	signed map[int]signed

	// forwarders are the globals holding the function values made for module functions read as values,
	// by the function each forwards to, and forwarderValues the declarations that make them, which run
	// before anything else (functionValue).
	forwarders      map[int]int
	forwarderValues []ir.Statement

	// unsetUntil is where, in the constructor being lowered, its last assignment of a field without an
	// initializer ends: before it, this is only for reading and writing fields (useOfThis).
	unsetUntil int

	// generics maps each generic module function's symbol to its declaration, and genericInstances
	// each instantiation already lowered to its function (generic.go). genericDepth counts the
	// instantiations being lowered inside one another.
	generics              map[*ast.Symbol]*ast.Node
	genericInstances      map[string]int
	classGenericInstances map[string]map[string]int
	genericDepth          int

	// caught are the variables a catch binds, each always an Error; tries are the try statements
	// lowered (exceptions.go).
	caught map[*ast.Symbol]bool
	tries  []tryRecord

	// initializing is the variables whose initializers are being lowered, by where each is declared.
	initializing map[int]*ast.Node

	// For the cycle finder (cycles.go): the checker's type of each local, and where it's declared;
	// every function value made, with its type; and the class type being instantiated, for this.
	localTypes     map[int]*checker.Type
	localAlso      map[int][]*checker.Type
	localNodes     map[int]*ast.Node
	closureRecords []closureRecord
	classType      *checker.Type
	classNode      *ast.Node

	// typeMapper is what the type parameters of the instantiation being lowered, and of those it's
	// inside, stand for; instantiated is every class type an instantiation was made for (instantiate.go).
	typeMapper   *typeMapper
	instantiated []*checker.Type

	// writeSites is every write into a slot lowering made, by its IR node's Site less one (fresh.go).
	writeSites       []writeSite
	accessorCaptures []accessorCapture
	accessorNames    map[string]bool
}
